    id: 'evolving-pad', name: 'Slowly Turning Pad', ref: 'In the style of Brian Eno — "Music for Airports"', artist: 'Brian Eno',
    tags: ['pad', 'ambient', '70s'], level: 3,
    blurb: 'A pad that slowly changes colour on its own while a chord holds.',
